create table Customer (age integer not null, totalPurchases float(53) not null, id bigint generated by default as identity, cardNumber varchar(16), name varchar(50) not null, primary key (id));
create table Family (id bigint generated by default as identity, name varchar(50) not null, primary key (id));
create table Product (discount float(53) not null, price float(53) not null, stock integer not null check (stock>=0), familyId bigint not null, id bigint generated by default as identity, valuationId bigint not null, name varchar(50) not null, URL varchar(250) not null, primary key (id));
create table ROLES (ROLENAME varchar(50) not null, primary key (ROLENAME));
create table USERS (ENABLED boolean not null, EXPIRY_DATE_ACCOUNT date not null, EXPIRY_DATE_CREDENTIALS date not null, LOCKED_ACCOUNT boolean not null, ID bigint generated by default as identity, USERNAME varchar(50) not null unique, EMAIL varchar(100) not null unique, PASSWORD varchar(100) not null, fullname varchar(100) not null, primary key (ID));
create table USERS_HAS_ROLES (FK_USERS_ID bigint not null, FK_ROLES_ROLENAME varchar(255) not null, primary key (FK_USERS_ID, FK_ROLES_ROLENAME));
create table Valuation (id bigint generated by default as identity, name varchar(50) not null, primary key (id));
alter table if exists Product add constraint FKo2739prt3726dwphva62dyi8n foreign key (familyId) references Family;
alter table if exists Product add constraint FKly89xto0enmi9251oul8waqam foreign key (valuationId) references Valuation;
alter table if exists USERS_HAS_ROLES add constraint FKmweugxov8fndr7t6mc1w3c8kp foreign key (FK_ROLES_ROLENAME) references ROLES;
alter table if exists USERS_HAS_ROLES add constraint FKbhfbxpypewmujo22f4b7vor8d foreign key (FK_USERS_ID) references USERS;
